/**
 * Sign release builds with a real upload key, when one is configured (M23).
 *
 * ## Why this is a config plugin and not an edit to build.gradle
 *
 * `android/` is generated by `expo prebuild` and is gitignored. Editing
 * `android/app/build.gradle` works exactly until the next `--clean` prebuild,
 * which ADR 0015 runs as a matter of course. A signing setup that a routine
 * command silently reverts is worse than none: the build still succeeds, still
 * produces an AAB, and Play rejects it at upload with a message about the
 * certificate rather than about what happened.
 *
 * So the change is expressed here, re-applied on every prebuild, and the
 * credentials it points at live outside the repository.
 *
 * ## Where the key lives, and why not here
 *
 * Four Gradle properties, read from `~/.gradle/gradle.properties`:
 *
 *     WGE_UPLOAD_STORE_FILE=/absolute/path/to/worst-gig-ever-upload.keystore
 *     WGE_UPLOAD_STORE_PASSWORD=…
 *     WGE_UPLOAD_KEY_ALIAS=upload
 *     WGE_UPLOAD_KEY_PASSWORD=…
 *
 * That file is in the user's home directory, not the working tree, so there is
 * no path by which `git add -A` reaches it. AGENTS.md rule 22 forbids
 * committing credentials, and the strongest way to honour that is for the
 * credential to have no filename inside the project at all.
 *
 * **Losing the keystore is unrecoverable** while Play App Signing is not
 * enabled, and merely annoying once it is — with Play App Signing, Google
 * holds the real app signing key and this is only the *upload* key, which
 * support can reset. That is the whole reason the recommendation is to let
 * Play manage signing.
 *
 * ## It degrades to the debug key rather than failing
 *
 * A developer with no upload key configured still gets a working release APK
 * signed with the debug keystore, exactly as before — that is what every local
 * performance test and friend build has used since 2026-09-04, and breaking it
 * to enforce a store rule would cost a workflow that works to protect an
 * upload nobody is doing yet.
 *
 * What must never happen is a debug-signed artifact being *mistaken* for an
 * uploadable one. That is `scripts/check-upload-signing.mjs`'s job, and
 * `npm run build:bundle` runs it.
 */
const { withAppBuildGradle } = require('@expo/config-plugins');

/** The Gradle property that decides whether an upload key is configured. */
const STORE_FILE_PROPERTY = 'WGE_UPLOAD_STORE_FILE';

const SIGNING_CONFIG = `
        // Added by plugins/withUploadSigning.js (M23). Do not edit here:
        // android/ is regenerated by \`expo prebuild\` and this will be lost.
        upload {
            if (project.hasProperty('${STORE_FILE_PROPERTY}')) {
                storeFile file(${STORE_FILE_PROPERTY})
                storePassword WGE_UPLOAD_STORE_PASSWORD
                keyAlias WGE_UPLOAD_KEY_ALIAS
                keyPassword WGE_UPLOAD_KEY_PASSWORD
            }
        }`;

/**
 * Picks the upload key when one is configured and the debug key otherwise.
 *
 * Evaluated at configuration time by Gradle, so a build either has the real
 * key or it does not — there is no state in which it half has one.
 */
const RELEASE_SIGNING =
  `signingConfig project.hasProperty('${STORE_FILE_PROPERTY}') ` +
  '? signingConfigs.upload : signingConfigs.debug';

module.exports = function withUploadSigning(config) {
  return withAppBuildGradle(config, (gradleConfig) => {
    let contents = gradleConfig.modResults.contents;

    if (contents.includes('withUploadSigning.js')) return gradleConfig;

    /*
     * Anchored on the debug signingConfig block that the React Native template
     * generates, rather than on a line number or a loose brace match. If the
     * template changes shape, this throws instead of writing the config
     * somewhere harmless-looking — a signing block in the wrong scope is
     * ignored by Gradle, and the failure would be a debug-signed AAB that
     * looks configured.
     */
    const debugBlockEnd = /(signingConfigs \{[\s\S]*?keyPassword 'android'\n\s*\})/;
    if (!debugBlockEnd.test(contents)) {
      throw new Error(
        'withUploadSigning: could not find the template debug signingConfig block in ' +
          'app/build.gradle. The template changed shape; update this plugin rather than ' +
          'letting it write the signing config into the wrong scope.',
      );
    }
    contents = contents.replace(debugBlockEnd, `$1${SIGNING_CONFIG}`);

    /*
     * The template ships `release { signingConfig signingConfigs.debug }` with
     * a comment above it telling you to generate your own keystore. That line
     * is the one being replaced, and matching it exactly means a template that
     * already signs correctly is left alone.
     */
    const releaseSigning = /release \{\n(\s*)\/\/ Caution!.*\n\s*\/\/ see.*\n\s*signingConfig signingConfigs\.debug/;
    if (!releaseSigning.test(contents)) {
      throw new Error(
        'withUploadSigning: could not find the template release signingConfig line in ' +
          'app/build.gradle. Update this plugin rather than shipping a release build ' +
          'whose signing key nobody checked.',
      );
    }
    contents = contents.replace(
      releaseSigning,
      `release {\n$1${RELEASE_SIGNING}`,
    );

    gradleConfig.modResults.contents = contents;
    return gradleConfig;
  });
};
